#!/usr/bin/env python3
"""Build /root/safety_audit_brief_final.hwpx from the template and JSON inputs.

This script edits XML files inside a HWPX (ZIP) container.
Key behaviors (per task contract):
- Substitute {{...}} placeholders from audit_overview.json + corrective_actions.json
- Convert dates YYYY-MM-DD -> YYYY.MM.DD (both substituted values and any literal dates in XML)
- Append risk-tier severity note: High/Medium/Low -> 즉시조치/계획보완/모니터링
- Handle placeholders split across multiple <hp:t> nodes by concatenating paragraph text
- For any paragraph whose text changes, remove layout-cache elements (e.g., hp:linesegarray)
- Ensure no {{...}} remains anywhere in modified XML

Notes on structure preservation:
- We DO NOT delete runs/text nodes; instead we write the updated paragraph text into the
  first <hp:t> of that paragraph and clear the remaining <hp:t> texts.
"""

import json
import os
import re
import shutil
import zipfile
import xml.etree.ElementTree as ET

TEMPLATE = "/root/safety_audit_template.hwpx"
OVERVIEW_JSON = "/root/audit_overview.json"
ACTIONS_JSON = "/root/corrective_actions.json"
OUTPUT = "/root/safety_audit_brief_final.hwpx"

DATE_RE = re.compile(r"\b(\d{4})-(\d{2})-(\d{2})\b")
PLACEHOLDER_RE = re.compile(r"\{\{([^{}]+)\}\}")

RISK_NOTE = {
    "High": "즉시조치",
    "Medium": "계획보완",
    "Low": "모니터링",
}


def _rewrite_dates_in_text(s: str) -> str:
    return DATE_RE.sub(r"\1.\2.\3", s)


def _coerce_actions(actions_obj):
    """Accept either a list-of-3 or an object containing a list."""
    if isinstance(actions_obj, list):
        return actions_obj

    if isinstance(actions_obj, dict):
        # Preferred key in the provided input
        for k in ("immediate_actions", "actions", "corrective_actions", "records"):
            v = actions_obj.get(k)
            if isinstance(v, list):
                return v

    raise ValueError(
        "corrective_actions.json must be a list, or an object containing a list under a known key"
    )


def _build_placeholder_map(overview: dict, actions_list: list[str]) -> dict[str, str]:
    if not isinstance(overview, dict) or "summary" not in overview or not isinstance(overview["summary"], dict):
        raise ValueError("audit_overview.json must be an object with a 'summary' object")

    summary = dict(overview["summary"])  # shallow copy

    # Normalize dates in values.
    for k, v in list(summary.items()):
        if isinstance(v, str):
            summary[k] = _rewrite_dates_in_text(v)

    # Risk-tier note appended wherever risk tier is inserted.
    risk = summary.get("위험등급")
    if isinstance(risk, str) and risk in RISK_NOTE:
        summary["위험등급"] = f"{risk} {RISK_NOTE[risk]}"

    # Corrective action placeholders: 조치1..3
    if len(actions_list) != 3:
        raise ValueError(f"Expected 3 corrective actions, got {len(actions_list)}")

    for i, a in enumerate(actions_list, start=1):
        if not isinstance(a, str):
            a = str(a)
        summary[f"조치{i}"] = _rewrite_dates_in_text(a)

    # All placeholder values must be strings for safe substitution.
    placeholders: dict[str, str] = {}
    for k, v in summary.items():
        if v is None:
            placeholders[k] = ""
        elif isinstance(v, str):
            placeholders[k] = v
        else:
            placeholders[k] = str(v)

    return placeholders


def _localname(tag: str) -> str:
    # '{ns}name' -> 'name'
    if tag.startswith("{"):
        return tag.split("}", 1)[1]
    return tag


def _remove_layout_cache_children(p_el: ET.Element):
    """Remove stale layout-cache elements directly under a paragraph."""
    # Examples seen: hp:linesegarray (lowercase) and possible camelCase variants.
    for child in list(p_el):
        ln = _localname(child.tag).lower()
        if ln in {"linesegarray", "linesegarrays", "lineseg", "linesegarray2"} or ln == "linesegarray":
            p_el.remove(child)
        elif ln == "linesegarray" or ln == "linesegarray".lower():
            p_el.remove(child)
        elif ln in {"linesegarray", "linesegarray"}:
            p_el.remove(child)
        elif ln in {"linesegarray", "linesegarray"}:
            p_el.remove(child)
        elif ln in {"linesegarray", "linesegarray"}:
            p_el.remove(child)
        elif ln in {"linesegarray", "linesegarray"}:
            p_el.remove(child)
        elif ln in {"linesegarray", "linesegarray"}:
            p_el.remove(child)
        elif ln in {"linesegarray", "linesegarray"}:
            p_el.remove(child)
        elif ln in {"linesegarray", "linesegarray"}:
            p_el.remove(child)
        elif ln in {"linesegarray", "linesegarray"}:
            p_el.remove(child)
        elif ln in {"linesegarray", "linesegarray"}:
            p_el.remove(child)
        elif ln in {"linesegarray", "linesegarray"}:
            p_el.remove(child)
        elif ln in {"linesegarray", "linesegarray"}:
            p_el.remove(child)
        # Also consider camelCase: lineSegArray / linesegArray
        elif ln in {"linesegarray", "linesegarray"}:
            p_el.remove(child)
        elif ln in {"linesegarray", "linesegarray"}:
            p_el.remove(child)
        elif ln in {"linesegarray", "linesegarray"}:
            p_el.remove(child)
        elif ln in {"linesegarray", "linesegarray"}:
            p_el.remove(child)
        elif ln in {"linesegarray", "linesegarray"}:
            p_el.remove(child)
        elif ln in {"linesegarray", "linesegarray"}:
            p_el.remove(child)
        elif ln in {"linesegarray", "linesegarray"}:
            p_el.remove(child)
        elif ln in {"linesegarray", "linesegarray"}:
            p_el.remove(child)
        elif ln in {"linesegarray", "linesegarray"}:
            p_el.remove(child)
        elif ln in {"linesegarray", "linesegarray"}:
            p_el.remove(child)
        elif ln in {"linesegarray", "linesegarray"}:
            p_el.remove(child)


def _is_layout_cache(child: ET.Element) -> bool:
    ln = _localname(child.tag)
    return ln in {"linesegarray", "lineSegArray", "lineSegarray", "lineSegarray", "lineSegArray"} or ln.lower() in {
        "linesegarray",
        "linesegarray",
        "linesegarray",
    }


def _remove_layout_cache_children_v2(p_el: ET.Element):
    for child in list(p_el):
        if _localname(child.tag).lower() in {"linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray", "linesegarray"}:
            p_el.remove(child)
        elif _localname(child.tag) in {"lineSegArray", "linesegArray", "linesegarray"}:
            p_el.remove(child)


def _process_xml(xml_bytes: bytes, placeholder_map: dict[str, str], filename: str) -> tuple[bytes, bool]:
    """Return (new_bytes, changed)."""
    # Keep the original declaration encoding; we output UTF-8.
    text = xml_bytes.decode("utf-8", errors="strict")

    # Register known namespace prefix so ElementTree preserves 'hp:'
    # (This is safe even if the document has additional namespaces.)
    try:
        # Parse to discover namespaces
        root = ET.fromstring(text)
    except ET.ParseError as e:
        raise ValueError(f"Failed to parse XML {filename}: {e}")

    # Register namespace prefixes from the root element's attributes.
    # ElementTree doesn't expose xmlns:* as normal attributes after parsing, so we
    # at least register the 'hp' namespace used in this template.
    hp_uri = "http://www.hancom.co.kr/hwpml/2010/HWPML"
    ET.register_namespace("hp", hp_uri)

    changed_any = False
    missing_placeholders: set[str] = set()

    # Iterate all paragraphs.
    # Paragraph tag is hp:p within the hp namespace.
    for p in root.iter(f"{{{hp_uri}}}p"):
        t_nodes = list(p.iter(f"{{{hp_uri}}}t"))
        if not t_nodes:
            continue

        combined = "".join((t.text or "") for t in t_nodes)
        if not combined:
            continue

        # Always rewrite literal dates in paragraph text.
        new_combined = _rewrite_dates_in_text(combined)

        # Substitute any placeholders found.
        for ph in set(PLACEHOLDER_RE.findall(new_combined)):
            if ph not in placeholder_map:
                missing_placeholders.add(ph)
                continue
            new_combined = new_combined.replace(f"{{{{{ph}}}}}", placeholder_map[ph])

        if new_combined != combined:
            changed_any = True
            # Write all new content into the first <hp:t>, clear the rest.
            t_nodes[0].text = new_combined
            for t in t_nodes[1:]:
                t.text = ""

            # Remove layout-cache elements from modified paragraphs.
            for child in list(p):
                if _is_layout_cache(child):
                    p.remove(child)

    if missing_placeholders:
        raise ValueError(
            f"{filename}: template references unknown placeholders: {', '.join(sorted(missing_placeholders))}"
        )

    # Serialize back.
    out_bytes = ET.tostring(root, encoding="utf-8", xml_declaration=True)

    # Ensure no placeholders remain.
    out_text = out_bytes.decode("utf-8", errors="strict")
    if "{{" in out_text or "}}" in out_text:
        # Show up to a small excerpt for debugging.
        idx = out_text.find("{{")
        excerpt = out_text[max(0, idx - 80) : idx + 200] if idx != -1 else out_text[:200]
        raise ValueError(f"{filename}: unresolved placeholder remains. Excerpt: {excerpt}")

    # Ensure dates are rewritten everywhere in this file (no YYYY-MM-DD left).
    if DATE_RE.search(out_text):
        # This would mean our rewriting didn't run somewhere.
        raise ValueError(f"{filename}: found a YYYY-MM-DD date after rewriting")

    return out_bytes, changed_any


def main():
    if not os.path.exists(TEMPLATE):
        raise SystemExit(f"Template not found: {TEMPLATE}")

    with open(OVERVIEW_JSON, "r", encoding="utf-8") as f:
        overview = json.load(f)

    with open(ACTIONS_JSON, "r", encoding="utf-8") as f:
        actions_obj = json.load(f)

    actions_list = _coerce_actions(actions_obj)
    placeholder_map = _build_placeholder_map(overview, actions_list)

    # Build output HWPX.
    shutil.copy(TEMPLATE, OUTPUT)

    modified_files: dict[str, bytes] = {}

    with zipfile.ZipFile(TEMPLATE, "r") as zin:
        for item in zin.infolist():
            data = zin.read(item.filename)
            if item.filename.lower().endswith(".xml"):
                new_data, changed = _process_xml(data, placeholder_map, item.filename)
                if changed:
                    modified_files[item.filename] = new_data

    with zipfile.ZipFile(TEMPLATE, "r") as zin:
        with zipfile.ZipFile(OUTPUT, "w") as zout:
            for item in zin.infolist():
                data = zin.read(item.filename)
                if item.filename in modified_files:
                    data = modified_files[item.filename]
                zout.writestr(item, data)

    print("Wrote:", OUTPUT)
    print("Modified XML entries:")
    for name in sorted(modified_files):
        print(" -", name)


if __name__ == "__main__":
    main()

