import os
import re
import shutil
import zipfile
import xml.etree.ElementTree as ET

TEMPLATE = "/root/safety_audit_template.hwpx"
OVERVIEW_JSON = "/root/audit_overview.json"
ACTIONS_JSON = "/root/corrective_actions.json"
OUTPUT = "/root/safety_audit_brief_final.hwpx"

