                if _is_layout_cache(child):
                    p.remove(child)

    if missing_placeholders:
        raise ValueError(
            f"{filename}: template references unknown placeholders: {', '.join(sorted(missing_placeholders))}"
        )

    out_bytes = ET.tostring(root, encoding="utf-8", xml_declaration=True)
    out_text = out_bytes.decode("utf-8", errors="strict")

    # Safety checks
    if "{{" in out_text or "}}" in out_text:
        idx = out_text.find("{{")
        excerpt = out_text[max(0, idx - 80) : idx + 200] if idx != -1 else out_text[:200]
        raise ValueError(f"{filename}: unresolved placeholder remains. Excerpt: {excerpt}")

    if DATE_RE.search(out_text):
        raise ValueError(f"{filename}: found a YYYY-MM-DD date after rewriting")

    return out_bytes, changed_any


def main() -> None:
    if not os.path.exists(TEMPLATE):
        raise SystemExit(f"Template not found: {TEMPLATE}")

    with open(OVERVIEW_JSON, "r", encoding="utf-8") as f:
        overview = json.load(f)

    with open(ACTIONS_JSON, "r", encoding="utf-8") as f:
        actions_obj = json.load(f)

    actions_list = _coerce_actions(actions_obj)
    placeholder_map, risk_raw = _build_placeholder_map(overview, actions_list)

    shutil.copy(TEMPLATE, OUTPUT)

    modified_files: dict[str, bytes] = {}

    with zipfile.ZipFile(TEMPLATE, "r") as zin:
        for item in zin.infolist():
            data = zin.read(item.filename)
            if item.filename.lower().endswith(".xml"):
                new_data, changed = _process_xml(data, placeholder_map, risk_raw, item.filename)
                if changed:
                    modified_files[item.filename] = new_data

    with zipfile.ZipFile(TEMPLATE, "r") as zin:
        with zipfile.ZipFile(OUTPUT, "w") as zout:
            for item in zin.infolist():
                data = zin.read(item.filename)
                if item.filename in modified_files:
                    data = modified_files[item.filename]
                zout.writestr(item, data)

    print("Wrote:", OUTPUT)
    print("Modified XML entries:")
    for name in sorted(modified_files):
        print(" -", name)


if __name__ == "__main__":
    main()
